import{_ as i,o as l,c as a,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"CDS Hammer (Day 2) - Shingled Erasure Code (SHEC)","description":"","frontmatter":{"title":"CDS Hammer (Day 2) - Shingled Erasure Code (SHEC)","date":"2014-10-30T00:00:00.000Z","updated":"2014-10-31T00:00:00.000Z","tags":["Shingled Erasure Code (Shake)","Ceph","Distributed Storage","Erasure Coding","Data Recovery"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2014/CDS_Hammer_Day_2_-_Shingled_Erasure_Code_SHEC.md","filePath":"posts/2014/CDS_Hammer_Day_2_-_Shingled_Erasure_Code_SHEC.md","lastUpdated":1780459816000}'),t={name:"posts/2014/CDS_Hammer_Day_2_-_Shingled_Erasure_Code_SHEC.md"};function o(s,e,_,n,S,h){return l(),a("div",null,[...e[0]||(e[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： Shingled Erasure Code (Shake) 介绍及讨论</p><p><strong>与会人员</strong>： 来自富士通的 Takeshi Miyamai 博士，以及其他 Ceph 开发者和测试人员</p><p><strong>会议内容</strong>：</p><ol><li><p><strong>Shake 介绍</strong>：</p><ul><li>Takeshi Miyamai 博士介绍了他们开发的名为 &quot;Shangri-La&quot; 的 Shingled Erasure Code (Shake)，这是一种高效的擦除码，能够在磁盘发生故障时快速恢复数据。</li><li>Shake 在 I/O Workshop 上展示了其初步成果，并寻求社区反馈以改进未来工作。</li><li>与现有的擦除码（如 DSA）相比，Shake 在多种磁盘故障情况下展现出更高的恢复效率。</li><li>Shake 的设计允许用户根据需要调整恢复效率，以平衡存储空间和恢复效率。</li></ul></li><li><p><strong>Shake 的特性</strong>：</p><ul><li>采用类似于 Check 1065 的布局，包含 10 个数据块和 6 个校验块。</li><li>校验块具有局部性，每个校验块只覆盖相邻的数据块。</li><li>在恢复数据时，只需读取少量校验块，从而减少了读取操作的数量。</li></ul></li><li><p><strong>Shake 的优势</strong>：</p><ul><li>在处理多磁盘故障时，Shake 具有更高的恢复效率，只需读取少量校验块即可恢复数据。</li><li>Shake 具有更高的调整性，用户可以根据需要调整恢复效率。</li><li>与现有的 Firefly 磁盘兼容。</li></ul></li><li><p><strong>Shake 的未来工作</strong>：</p><ul><li>扩展 Shake 的功能，使其能够支持更多的存储系统和错误检测机制。</li><li>在 Ceph 中集成 Shake，并与其他擦除码进行比较和测试。</li></ul></li><li><p><strong>后续行动计划</strong>：</p><ul><li>Takeshi Miyamai 博士将提供 Shake 的源代码，并与其他 Ceph 开发者合作，将其集成到 Ceph 中。</li><li>开发者将编写文档和单元测试，以确保 Shake 的正确性和稳定性。</li><li>社区成员将对 Shake 进行测试和反馈，以改进其功能。</li></ul></li></ol><p><strong>关键术语</strong>：</p><ul><li>Shingled Erasure Code (Shake)</li><li>擦除码</li><li>恢复效率</li><li>数据块</li><li>校验块</li><li>局部性</li><li>Firefly</li><li>Ceph</li></ul>',7)])])}const u=i(t,[["render",o]]);export{p as __pageData,u as default};
